describe('Column Sort Direction Arrow Icon', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('table').should('be.visible');
  });

  it('should display ascending arrow icon when column is sorted ascending', () => {
    cy.get('table thead th').first().click();
    cy.get('table thead th').first().within(() => {
      cy.get('[data-testid="sort-arrow"]').should('be.visible');
      cy.get('[data-testid="sort-arrow"]').should('have.class', 'ascending');
    });
  });

  it('should display descending arrow icon when column is sorted descending', () => {
    cy.get('table thead th').first().click();
    cy.get('table thead th').first().click();
    cy.get('table thead th').first().within(() => {
      cy.get('[data-testid="sort-arrow"]').should('be.visible');
      cy.get('[data-testid="sort-arrow"]').should('have.class', 'descending');
    });
  });

  it('should remove arrow icon when sort is cleared', () => {
    cy.get('table thead th').first().click();
    cy.get('table thead th').first().click();
    cy.get('table thead th').first().click();
    cy.get('table thead th').first().within(() => {
      cy.get('[data-testid="sort-arrow"]').should('not.exist');
    });
  });

  it('should update arrow icon when switching sort to different column', () => {
    cy.get('table thead th').first().click();
    cy.get('table thead th').first().within(() => {
      cy.get('[data-testid="sort-arrow"]').should('have.class', 'ascending');
    });

    cy.get('table thead th').eq(1).click();
    cy.get('table thead th').first().within(() => {
      cy.get('[data-testid="sort-arrow"]').should('not.exist');
    });
    cy.get('table thead th').eq(1).within(() => {
      cy.get('[data-testid="sort-arrow"]').should('be.visible');
      cy.get('[data-testid="sort-arrow"]').should('have.class', 'ascending');
    });
  });

  it('should display correct arrow icon for multiple column headers', () => {
    cy.get('table thead th').each(($header) => {
      cy.wrap($header).within(() => {
        cy.get('[data-testid="sort-arrow"]').should('not.exist');
      });
    });
  });
});
